/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share
 * this owner's {@code firstName} and {@code lastName}, compared case-insensitively.
 *
 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and the count
 * reflects only the owners that existed before this create.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(existing.getFirstName(), firstName)
                    && equalsIgnoreCase(existing.getLastName(), lastName)) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

